package com.wipro.spring; public class Player { private String playerId,playerName; private Country country; public String getPlayerId(){return playerId;} public void setPlayerId(String v){playerId=v;} public String getPlayerName(){return playerName;} public void setPlayerName(String v){playerName=v;} public Country getCountry(){return country;} public void setCountry(Country v){country=v;} public void print(){System.out.println(playerId+" | "+playerName+" | "+country.getCountryName());} }